  "courseIntro": {
    "title": "សេចក្តីផ្តើមនៃមុខវិជ្ជា",
    "content": "## ១. ការពិពណ៌នា​អំពី​មុខវិជ្ជា\n\nមុខវិជ្ជា​នេះ ដែល​ត្រូវបាន​រៀបចំ​សម្រាប់​និស្សិត​ថ្នាក់​ឆ្នាំ​សិក្សា​មូលដ្ឋាន។ ហើយ​នឹង​បង្ហាត់​និស្សិត​គ្រប់​មហាវិទ្យាល័យ​ទាំងអស់​នៃ វិទ្យាស្ថាន​ពហុ​បច្ចេកទេស​ភូមិភាគ​តេជោ​សែន​សៀមរាប​ទាំង​និស្សិត​ជំនាញ​ព័ត៌មានវិទ្យា និង​ជំនាញ​ផ្សេងៗ​ទៀត។ មុខវិជ្ជា​នេះ​ដែរ​នឹង​ផ្ដល់​ឱកាស​ឱ្យ​និស្សិត​សិក្សា​ពី​ជំនាញ​មូលដ្ឋាន​របស់​កុំព្យូទ័រ និង​ការប្រើប្រាស់​កម្មវិធី​រួមមានៈ ការគ្រប់គ្រង​ឯកសារ​, ការរៀបចំ​ឯកសារ​សម្រាប់​កិច្ចការ​រដ្ឋបាល​, ការគ្រប់គ្រង​ទិន្នន័យ​ក្នុង​តារាង​, ការរៀបចំ​បទ​បង្ហាញ​, ស្វែងរក និង​បញ្ជូន​ឯកសារ​លក្ខណៈ​សកល ដើម្បី​ឆ្លើយតប​ទៅនឹង​ការសិក្សា​ស្រាវជ្រាវ​រក​ឯកសារ ឬ​កិច្ចការ​នានា​របស់​វិទ្យាស្ថាន និង​កិច្ចការ​រដ្ឋបាល​មួយចំនួន​ទៀត។\n\nមុខវិជ្ជា​កុំព្យូទ័រ​អនុវត្តន៍​ក្នុង​ការិយាល័យ (Computer for Office Application) ត្រូវបាន​រៀបចំ​សម្រាប់​រយៈពេល​៤៥ ម៉ោង នៅក្នុង​ឆ្នាំ​ទី១ ឆមាស​ទី១ ដោយ​ផ្ដោត​ទៅ​លើ​ចំណេះដឹង​ទូទៅ​ដែល​ទាក់ទង​នឹង​កុំព្យូទ័រ​មាន​ដូចជា៖\n- ការរៀបចំ​ឯកសារ​សម្រាប់​កិច្ចការ​រដ្ឋបាល​ដោយ​ប្រើ Microsoft Office Word\n- ការគ្រប់គ្រង​ទិន្នន័យ​ក្នុង​តារាង​ដោយ​ប្រើ Microsoft Office Excel\n- ការរៀបចំ​បទ​បង្ហាញ​ដោយ​ប្រើ Microsoft Office PowerPoint\n\n## ២. គោលបំណង​នៃ​មុខវិជ្ជា\n\nគោលបំណង​នៃ​ការសិក្សា​កុំព្យូទ័រ​អនុវត្តន៍​ក្នុង​ការិយាល័យ គឺ​កសាង​សមត្ថភាព​របស់​និស្សិត​នូវ​ចំណេះដឹង​ក្នុង​ការប្រើប្រាស់​កុំព្យូទ័រ ដើម្បី​ដោះស្រាយ​ការងារ​ចាំបាច់​មួយ​ចំនួន​ទាំង​ក្នុង​ការសិក្សា និង​ស្រាវជ្រាវ។ ក្រោយពី​ការសិក្សា​មុខវិជ្ជា​នេះ​រួច​និស្សិត​មាន​លទ្ធភា​ព៖\n- ប្រើ Microsoft Office Word ដើម្បី​បង្កើត​និង​រៀបចំ​ឯកសារ​ដែល​ទាក់ទង​នឹង​ការងារ\n- ប្រើ Microsoft Office Excel ដើម្បី​បង្កើត​ជា​តារាង និង​ធ្វើ​ការគណនា​ប្រមាណ​វិធី​ផ្សេងៗ\n- ប្រើ Microsoft Office PowerPoint ដើម្បី​បង្កើត​ជា Slide សម្រាប់​ធ្វើ​ការបង្ហាញ​ណែនាំ"
  },
