              "text": "សម្រាប់​ប្រតិបត្តិការ​លើ​ការគណនា​តម្លៃ​, ការគណនា​ប្រមាណ​វិធី ដូចជា​គណិតសាស្ត្រ​, ត្រីកោណ​មាត្រសាស្ត្រ​, ស្ថិតិ​, កាលបរិច្ឆេទ​និង​ពេលវេលា​, តក្កវិជ្ជា​, គណនេយ្យ​, ហិរញ្ញវត្ថុ​, ស្រង់​ទិន្នន័យ និង ការគ្រប់គ្រង​ទិន្នន័យ​ផ្សេងៗ។ ការគណនា​នេះ ត្រូវបាន​ធ្វើឡើង​នៅក្នុង Cell នីមួយៗ​ដែល​អ្នក​ចង់​បង្ហាញ​តម្លៃ​លទ្ធផល​នោះ។ ចំណុច​ដែល​ត្រូវ​កត់សម្គាល់​នោះ​គឺ រាល់​ការគណនា​ត្រូវ​សរសេរ​ផ្តើម​ឡើង​ដោយ​សញ្ញា​ស្មើ (=) ភ្ជាប់​ដោយ​អនុគមន៍ (រូបមន្ត) ផ្សេងៗ។"
